@gene('s4', 'how much closer a step brings me to the goals; gem carriers (12+) and hurt champions (<55%) shy from tiles within 2 of enemy champions (per-pass mask), extra when adjacent; penalty grows with gems carried and missing health')
def progress(t: Tile) -> Num:
    f = goal_field()
    d = at(f, me().pos) - at(f, t)
    if d > 0:
        g = gems()
        hf = me().health_frac
        if g >= 12 or hf < 0.55:
            if t in foe_reach2():
                w = 0.55 + g / 80 + (1 - hf) * 0.5
                if hf < 0.4:
                    w = w + 0.3
                if size(near(t, 1) & foe_champ_tiles()) > 0:
                    w = w + 0.4
                d = d - w
    return d
