@gene('s2', 'where to walk: altar with gems (bank at 10, at 5+ when hurt, any after 1750, or when banking wins the game); else cleared groups waiting for capture first, else living non-monolith camps (golem groups only after round 600 or if nothing else); altars only computed when carrying')
def goals() -> Tiles:
    g_now = gems()
    al = near(tile(-5, -5), 0)
    if g_now > 0:
        al = altar_goals()
    hf = me().health_frac
    if g_now >= 10 or (g_now >= 5 and hf < 0.5) or (g_now > 0 and (round() > 1750 or team_gems() + g_now >= 1000)):
        if size(al) > 0:
            return al
    mono = type_spawns(MONOLITH)
    golem = type_spawns(GOLEM)
    early = round() < 600
    rew = near(tile(-5, -5), 0)
    acc = near(tile(-5, -5), 0)
    hard = near(tile(-5, -5), 0)
    for g in range(num_groups()):
        if group_reward(g):
            rew = rew | group_tiles(g)
        elif not group_respawning(g):
            ts = group_tiles(g)
            if size(ts & mono) == 0:
                if early and size(ts & golem) > 0:
                    hard = hard | ts
                else:
                    acc = acc | ts
    if size(acc) == 0:
        acc = hard
    if size(rew) > 0:
        acc = rew
    if g_now > 0:
        acc = acc | al
    return acc
```

